function describe(a, b, c, d, e, f, g) {
  if (a) {
    return "a";
  }
  if (b) {
    return "b";
  }
  if (c) {
    return "c";
  }
  if (d) {
    return "d";
  }
  if (e) {
    return "e";
  }
  if (f) {
    return "f";
  }
  return g;
}

function summarizeOrders(orders) {
  let total = 0;
  let count = 0;
  let largest = 0;
  const names = [];
  for (const order of orders) {
    total += order.amount;
    count += 1;
    if (order.amount > largest) {
      largest = order.amount;
    }
    if (order.name) {
      names.push(order.name);
    }
    if (order.note) {
      names.push(order.note);
    }
  }
  return { total, count, largest, names };
}

function summarizeInvoices(invoices) {
  let sum = 0;
  let items = 0;
  let biggest = 0;
  const labels = [];
  for (const invoice of invoices) {
    sum += invoice.value;
    items += 1;
    if (invoice.value > biggest) {
      biggest = invoice.value;
    }
    if (invoice.label) {
      labels.push(invoice.label);
    }
    if (invoice.memo) {
      labels.push(invoice.memo);
    }
  }
  return { sum, items, biggest, labels };
}

module.exports = { describe, summarizeOrders, summarizeInvoices };
